import{_ as n,l as r,o as e,c as s,v as t,p as l,x as o,d,i as p,S as E}from"./chunks/framework.InCnrqk-.js";const S=JSON.parse('{"title":"处置效应","description":"","frontmatter":{"title":"处置效应","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/disposition-effect.md","filePath":"econ/disposition-effect.md","lastUpdated":1789023840000}'),c={name:"econ/disposition-effect.md"};function h(A,a,B,f,_,m){const i=r("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="处置效应" tabindex="-1">处置效应 <a class="header-anchor" href="#处置效应" aria-label="Permalink to &quot;处置效应&quot;">​</a></h1><div class="epigraph"><p>浮盈愿意兑现，浮亏继续扛着——参考点是买入价，实现把账户结算成确定的收益或损失。</p><footer>—— Shefrin and Statman, The Disposition to Sell Winners Too Early and Ride Losers Too Long, Journal of Finance, 1985；Odean, JF 1998</footer></div><p><a href="/econ/prospect-theory-asset-pricing">上一课</a>把 \\(v\\) 放进定价。本课缺口是交易：同一损失厌恶预测<strong>实现行为</strong>不对称。不重校准溢价。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>规范模型按预期收益与风险决定卖不卖，买入价是沉没。Shefrin 与 Statman（1985）用前景理论加心理账户：每只股票一个账户，参考点买入价；实现收益落在 \\(v\\) 的凹段（厌恶风险，想锁定），浮亏落在凸段（寻求风险，想赌回来）。Odean（1998）用经纪账户：相对风险调整后的机会，投资者更常卖赢的。缺口是把参考点钉在成本，而不是再写市场均衡。</p><p>税的规范预测相反：应实现亏损抵税、推迟浮盈。处置效应与税冲突，识别更干净。</p><p><span class="marginnote">再平衡、流动性需求也会卖赢的（赢的变大了）。Odean 用卖出后的平均表现对照：卖掉的赢组合后来仍跑赢留下的亏组合，不像最优再平衡。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>持仓层面：实现概率对浮盈虚变量回归，控制持有期与波动。实验：诱导买入价，看卖出。本课不估计系数。与禀赋效应的差别：禀赋是 WTA/WTP，处置是跨期实现选择；零件都是损失厌恶加账户。</p>',9)),(e(),l(E,null,{default:o(()=>[p(i,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20LA%5B%22%E6%8D%9F%E5%A4%B1%E5%8E%8C%E6%81%B6%20%2B%20%E4%B9%B0%E5%85%A5%E4%BB%B7%E5%8F%82%E8%80%83%E7%82%B9%22%5D%20--%3E%20ACC%5B%22%E6%AF%8F%E5%8F%AA%E8%82%A1%E7%A5%A8%E4%B8%80%E4%B8%AA%E8%B4%A6%E6%88%B7%22%5D%0A%20%20ACC%20--%3E%20WIN%5B%22%E6%B5%AE%E7%9B%88%3A%20%E5%87%B9%E6%AE%B5%2C%20%E9%94%81%E5%AE%9A%22%5D%0A%20%20ACC%20--%3E%20LOSS%5B%22%E6%B5%AE%E4%BA%8F%3A%20%E5%87%B8%E6%AE%B5%2C%20%E7%BB%A7%E7%BB%AD%E6%8C%81%E6%9C%89%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>机制是结算。未实现时，人还在凸或凹的段上做赌博；实现把结果变成确定的得或失，编辑规则鼓励把确定收益留下、把确定损失推迟。这与动量可以互动：该卖的赢不卖会减少动量供给，该卖的亏不卖会推迟价格对坏消息的调整——信念模型不是唯一的漂移来源。</p><p>家庭金融：处置提高换手的同时降低净收益，叠加过度自信。本课以评价为主。</p><p>买入价当参考点，实现是编辑：确定收益落在凹段想锁住，确定损失落在凸段想赌回来。税的规范相反，故不能用「理性避税」一笔勾销。Odean 对照卖出后表现，排除单纯再平衡。漂移可以部分来自该卖的亏没卖、坏消息进价格慢——信念模型不是唯一通道。不把止损单的排队写成处置；那是协议，本课是账户结算。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>专业交易者、可转债强制条款、止损单会减弱效应。买入价作为参考点在多次加仓时含糊。本课不把所有「扛着亏」写成前景理论：卖空限制、没有替代资金，也会让人扛。也不写止损在簿上的排队。</p><p>后课默认：异质信念加卖空限制是另一条泡沫通道，不必经过买入价账户。</p><p>买入价当参考点，实现把账户结算成确定得失；凹段锁赢，凸段扛亏。税的规范相反。</p><p>Odean 用卖出后表现排除单纯再平衡。该卖的亏没卖，坏消息可以进价格更慢。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>处置效应：卖赢留亏，参考点成本，与税的规范相反。</li><li>心理账户把每只股票单独送进 \\(v\\) 的凹/凸段。</li><li>可与漂移叠加，但不替代 BSV/DHS 的信念故事。</li><li>多次加仓时参考点含糊。</li><li>止损排队是协议，本课是账户结算。</li><li>出处：Shefrin and Statman, <em>JF</em> 1985；Odean, <em>JF</em> 1998。</li></ul>',11))])}const T=n(c,[["render",h]]);export{S as __pageData,T as default};
